      ? safeHref(c.url, CFG.prUrl(c.repo, num, 'issues'))
      : CFG.prUrl(c.repo, num);
    var badges = badgesHtml(c);
    var checks = c.checks
      ? '<span class="checks"><span class="dot ' + verdictClass(c.checks.verdict) +
        '"></span><span>' + esc(c.checks.verdict) + ' · ' + esc(ago(c.checks.at)) +
        '</span></span>'
