    var isIssue = c.issue != null;
    var num = isIssue ? c.issue : c.pr;
    var href = isIssue
      ? safeHref(c.url, CFG.prUrl(c.repo, num, 'issues'))
      : CFG.prUrl(c.repo, num);
    var badges = badgesHtml(c);
    var checks = c.checks
