# measure on the real board: use dump-dom with an injected script won't work directly; instead measure via a wrapper page that iframes the board
cat > /tmp/clampprobe/board_measure.html <<'EOF'
<!doctype html><html><body>
<iframe id="f" src="file:///home/runner/work/dmtools-agents/dmtools-agents/site/factory/index.html?fixture=/tmp/clampprobe/fixture_long.json&theme=dark" style="width:1440px;height:900px;border:0"></iframe>
<pre id="out">pending</pre>
<script>
var f = document.getElementById('f');
f.onload = function () {
  setTimeout(function () {
    var doc = f.contentDocument;
    var titles = doc.querySelectorAll('.title');
    var report = [];
    for (var i = 0; i < titles.length; i++) {
      var t = titles[i];
      var r = t.getBoundingClientRect();
      if (r.height > 40) { // 3 lines x 14.4px line-height approx -> flag anything > 2 lines
        // find the sibling row that follows the card-top (labels/meta)
        var card = t.closest('.card');
        var labels = card ? card.querySelector('.labels') : null;
        var lr = labels ? labels.getBoundingClientRect() : null;
        report.push('title h=' + r.height.toFixed(1) +
          ' bottom=' + r.bottom.toFixed(1) +
          (lr ? ' labelsTop=' + lr.top.toFixed(1) + ' OVERLAP=' + (r.bottom > lr.top ? 'YES ink would bleed' : 'no') : ' no-labels'));
      }
    }
    document.getElementById('out').textContent = 'titles>2lines: ' + report.length + ' | ' + report.join(' || ');
  }, 2500);
};
</script></body></html>
EOF
